    Determines if the starting player (B, who moves from state 1) has a winning strategy
    for a given target N.
    DP[n] = 1 if the player whose turn it is from state n wins.
    DP[n] = 0 if the player whose turn it is from state n loses.
    """
    if N <= 1:
        return "N/A"

    # DP array stores the outcome for the current player from state n.
    # We only need up to N-1. DP[N] is not used as the game ends at N.
    dp = {} 

    # Iterate backwards from N-1 down to 1
    for n in range(N - 1, 0, -1):

        can_win = False

        # Check move n+1
        m1 = n + 1
        if m1 == N:
            can_win = True
        elif m1 < N:
            # If the opponent loses from m1 (DP[m1] == 0), we win by moving there.
            if dp[m1] == 0:
                can_win = True

        if can_win:
            dp[n] = 1
            continue

        # Check move 2*n
        m2 = 2 * n
        if m2 == N:
            can_win = True
        elif m2 < N:
            # If the opponent loses from m2 (DP[m2] == 0), we win by moving there.
            if dp[m2] == 0:
                can_win = True

        if can_win:
            dp[n] = 1
        else:
            # If all available moves lead to winning positions for the opponent, we lose.
            dp[n] = 0

    # The starting player is B, who moves from state 1.
    # If DP[1] == 1, B wins -> Type B.
    # If DP[1] == 0, B loses -> Type A.
    return dp.get(1)

