        can_win = False
        moves = []
        if n + 1 <= N:
            moves.append(n + 1)
        if 2 * n <= N:
            moves.append(2 * n)

        for next_n in moves:
            if next_n == N:
                can_win = True
                break
            else:
                if not W[next_n]:
                    can_win = True
                    break

        W[n] = can_win

    return W[1]

